"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_mathematics_de"]=window.LC_CHUNKS["university_mathematics_de"]||{};window.LC_CHUNKS["university_mathematics_de"][9]={"university_mathematics_de:M9-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M9-L1 – Bedingte Erwartung und Martingale<\/h1>\n<p><strong>Kursbereich:<\/strong> M9 – Stochastik, Finanz- und Versicherungsmathematik<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M3&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M3-L1<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M3&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M3-L4<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor-Vertiefung und Brücke zum\nMaster<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du berechnest bedingte Erwartungen auf endlichen\nWahrscheinlichkeitsräumen, formulierst ihre maßtheoretische\nCharakterisierung und verwendest die Turmeigenschaft. Du prüfst die\nMartingaleigenschaft einer symmetrischen Zufallsbewegung und beweist den\nErwartungswerterhalt bei beschränkten Stoppzeiten. Du erkennst, weshalb\neine fast sicher endliche Stoppzeit allein nicht ausreicht.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Bedingte Erwartung als Informationsprojektion<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Ω<\/mi><mo>,<\/mo><mi mathvariant=\"script\">ℱ<\/mi><mo>,<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(\\Omega,\\mathcal F,P)<\/annotation><\/semantics><\/math>\nein Wahrscheinlichkeitsraum und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>\nintegrierbar, also\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>X<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&lt;<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E|X|&lt;\\infty<\/annotation><\/semantics><\/math>.\nEine\nUnter-<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>σ<\/mi><annotation encoding=\"application/x-tex\">\\sigma<\/annotation><\/semantics><\/math>-Algebra\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"script\">𝒢<\/mi><mo>⊆<\/mo><mi mathvariant=\"script\">ℱ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal G\\subseteq\\mathcal F<\/annotation><\/semantics><\/math>\nbeschreibt beobachtbare Ereignisse. Die bedingte Erwartung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>X<\/mi><mo>∣<\/mo><mi mathvariant=\"script\">𝒢<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Y=E[X\\mid\\mathcal G]<\/annotation><\/semantics><\/math>\nist eine integrierbare,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">𝒢<\/mi><annotation encoding=\"application/x-tex\">\\mathcal G<\/annotation><\/semantics><\/math>-messbare\nZufallsvariable mit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∫<\/mo><mi>A<\/mi><\/msub><mi>Y<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>P<\/mi><mo>=<\/mo><msub><mo>∫<\/mo><mi>A<\/mi><\/msub><mi>X<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>P<\/mi><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>A<\/mi><mo>∈<\/mo><mi mathvariant=\"script\">𝒢<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\int_A Y\\,dP=\\int_A X\\,dP\\qquad(A\\in\\mathcal G).<\/annotation><\/semantics><\/math><\/p>\n<p>Existenz folgt aus dem Satz von Radon–Nikodym, angewandt auf die\nsignierte Maßfunktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>↦<\/mo><msub><mo>∫<\/mo><mi>A<\/mi><\/msub><mi>X<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>P<\/mi><\/mrow><annotation encoding=\"application/x-tex\">A\\mapsto\\int_A X\\,dP<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">𝒢<\/mi><annotation encoding=\"application/x-tex\">\\mathcal G<\/annotation><\/semantics><\/math>.\nEindeutigkeit gilt bis auf Nullmengen: Für zwei Kandidaten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>,<\/mo><mi>Z<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Y,Z<\/annotation><\/semantics><\/math>\nliefert die Wahl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>Y<\/mi><mo>&gt;<\/mo><mi>Z<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=\\{Y&gt;Z\\}<\/annotation><\/semantics><\/math>\ndas Integral einer positiven Differenz gleich null; entsprechend für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Z<\/mi><mo>&gt;<\/mo><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z&gt;Y<\/annotation><\/semantics><\/math>.\nAuf den Zellen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>A<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">A_j<\/annotation><\/semantics><\/math>\neiner endlichen Partition mit positiver Wahrscheinlichkeit gilt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>A<\/mi><mi>j<\/mi><\/msub><\/msub><mo>=<\/mo><mfrac><mrow><munder><mo>∑<\/mo><mrow><mi>ω<\/mi><mo>∈<\/mo><msub><mi>A<\/mi><mi>j<\/mi><\/msub><\/mrow><\/munder><mi>X<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>A<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/mfrac><\/mrow><annotation encoding=\"application/x-tex\">Y|_{A_j}=\\frac{\\sum_{\\omega\\in A_j}X(\\omega)P(\\{\\omega\\})}{P(A_j)}<\/annotation><\/semantics><\/math><\/p>\n<p>für endliches\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Ω<\/mi><annotation encoding=\"application/x-tex\">\\Omega<\/annotation><\/semantics><\/math>.\nZellen mit Wahrscheinlichkeit null beeinflussen das Ergebnis nicht.\nBeispiel: Vier gleichwahrscheinliche Ergebnisse tragen Werte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2,4,0,10<\/annotation><\/semantics><\/math>.\nDie Information unterscheidet nur die ersten beiden von den letzten\nbeiden. Dann sind die bedingten Werte 3 und 5, der unbedingte Mittelwert\n4.<\/p>\n<p>Aus der Integralcharakterisierung folgt Linearität. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"script\">ℋ<\/mi><mo>⊆<\/mo><mi mathvariant=\"script\">𝒢<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal H\\subseteq\\mathcal G<\/annotation><\/semantics><\/math>\ngilt die Turmeigenschaft\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>X<\/mi><mo>∣<\/mo><mi mathvariant=\"script\">𝒢<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>∣<\/mo><mi mathvariant=\"script\">ℋ<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>X<\/mi><mo>∣<\/mo><mi mathvariant=\"script\">ℋ<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[E[X\\mid\\mathcal G]\\mid\\mathcal H]=E[X\\mid\\mathcal H]<\/annotation><\/semantics><\/math>,\ndenn beide Seiten besitzen auf jedem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>∈<\/mo><mi mathvariant=\"script\">ℋ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">A\\in\\mathcal H<\/annotation><\/semantics><\/math>\ndas gleiche Integral. Insbesondere ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>Y<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>X<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[Y]=E[X]<\/annotation><\/semantics><\/math>.\nFür beschränktes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">𝒢<\/mi><annotation encoding=\"application/x-tex\">\\mathcal G<\/annotation><\/semantics><\/math>-messbares\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>H<\/mi><annotation encoding=\"application/x-tex\">H<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>H<\/mi><mi>X<\/mi><mo>∣<\/mo><mi mathvariant=\"script\">𝒢<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>H<\/mi><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>X<\/mi><mo>∣<\/mo><mi mathvariant=\"script\">𝒢<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[HX\\mid\\mathcal G]=H E[X\\mid\\mathcal G]<\/annotation><\/semantics><\/math>\n(zuerst für Indikatoren, dann einfache Funktionen, schließlich durch\nbeschränkte Approximation). Ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>\nunabhängig von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">𝒢<\/mi><annotation encoding=\"application/x-tex\">\\mathcal G<\/annotation><\/semantics><\/math>,\nso ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Y<\/mi><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>X<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Y=E[X]<\/annotation><\/semantics><\/math>\nkonstant. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X<\/mi><mo>∈<\/mo><msup><mi>L<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">X\\in L^2<\/annotation><\/semantics><\/math>\nfolgt zunächst aus bedingter Jensen-Ungleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>Y<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>≤<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>X<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[Y^2]\\le E[X^2]<\/annotation><\/semantics><\/math>.\nDann gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>X<\/mi><mo>−<\/mo><mi>Y<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>Z<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[(X-Y)Z]=0<\/annotation><\/semantics><\/math>\nfür jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"script\">𝒢<\/mi><annotation encoding=\"application/x-tex\">\\mathcal G<\/annotation><\/semantics><\/math>-messbare\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Z<\/mi><mo>∈<\/mo><msup><mi>L<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">Z\\in L^2<\/annotation><\/semantics><\/math>;\ndurch Approximation aus der Integralcharakterisierung. Daher minimiert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Y<\/mi><annotation encoding=\"application/x-tex\">Y<\/annotation><\/semantics><\/math>\nden mittleren quadratischen Vorhersagefehler unter solchen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Z<\/mi><annotation encoding=\"application/x-tex\">Z<\/annotation><\/semantics><\/math>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>X<\/mi><mo>−<\/mo><mi>Z<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>X<\/mi><mo>−<\/mo><mi>Y<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>+<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>Y<\/mi><mo>−<\/mo><mi>Z<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[(X-Z)^2]=E[(X-Y)^2]+E[(Y-Z)^2]<\/annotation><\/semantics><\/math>.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Filtration und Martingale<\/h2>\n<p>Eine Filtration\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi>n<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">(\\mathcal F_n)_{n\\ge0}<\/annotation><\/semantics><\/math>\nist eine wachsende Folge von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>σ<\/mi><annotation encoding=\"application/x-tex\">\\sigma<\/annotation><\/semantics><\/math>-Algebren.\nEin Prozess\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>M<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(M_n)<\/annotation><\/semantics><\/math>\nist adaptiert, wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>M<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">M_n<\/annotation><\/semantics><\/math>\nbereits anhand der Information\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\mathcal F_n<\/annotation><\/semantics><\/math>\nbestimmbar ist. Er ist ein Martingal, wenn jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>M<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">M_n<\/annotation><\/semantics><\/math>\nintegrierbar und adaptiert ist und<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>M<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mi>M<\/mi><mi>n<\/mi><\/msub><mspace width=\"1.0em\"><\/mspace><mtext mathvariant=\"normal\">fast sicher<\/mtext><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[M_{n+1}\\mid\\mathcal F_n]=M_n\\quad\\text{fast sicher}.<\/annotation><\/semantics><\/math><\/p>\n<p>Durch Iteration der Turmeigenschaft folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>M<\/mi><mi>m<\/mi><\/msub><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mi>M<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">E[M_m\\mid\\mathcal F_n]=M_n<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>≥<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">m\\ge n<\/annotation><\/semantics><\/math>.\nEin konstanter Erwartungswert allein reicht nicht: Die Bedingung muss\nfür die jeweilige Vergangenheit gelten. Bei Submartingalen steht\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mo>≥<\/mo><annotation encoding=\"application/x-tex\">\\ge<\/annotation><\/semantics><\/math>,\nbei Supermartingalen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mo>≤<\/mo><annotation encoding=\"application/x-tex\">\\le<\/annotation><\/semantics><\/math>\nstatt Gleichheit.<\/p>\n<p>Seien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">X_i<\/annotation><\/semantics><\/math>\nunabhängige Schritte mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(X_i=1)=P(X_i=-1)=1/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msubsup><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/msubsup><msub><mi>X<\/mi><mi>i<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">S_n=\\sum_{i=1}^n X_i<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mi>σ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><mi>…<\/mi><mo>,<\/mo><msub><mi>X<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal F_n=\\sigma(X_1,\\ldots,X_n)<\/annotation><\/semantics><\/math>.\nWeil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><annotation encoding=\"application/x-tex\">X_{n+1}<\/annotation><\/semantics><\/math>\nunabhängig von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\mathcal F_n<\/annotation><\/semantics><\/math>\nist, gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>S<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mi>S<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">E[S_{n+1}\\mid\\mathcal F_n]=S_n<\/annotation><\/semantics><\/math>.\nAußerdem ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>S<\/mi><mi>n<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">S_n^2-n<\/annotation><\/semantics><\/math>\nein Martingal, denn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo>+<\/mo><msub><mi>X<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msubsup><mi>S<\/mi><mi>n<\/mi><mn>2<\/mn><\/msubsup><mo>+<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[(S_n+X_{n+1})^2\\mid\\mathcal F_n]=S_n^2+1<\/annotation><\/semantics><\/math>.\nFür eine integrierbare Endgröße\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Z<\/mi><annotation encoding=\"application/x-tex\">Z<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>Z<\/mi><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">M_n=E[Z\\mid\\mathcal F_n]<\/annotation><\/semantics><\/math>\nebenfalls ein Martingal (Turmeigenschaft).<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_040_DE.svg\"\nalt=\"Zweistufiger Random Walk mit bedingten Wahrscheinlichkeiten 1/2 und Knotenwerten.\" />\n<figcaption aria-hidden=\"true\">Zweistufiger Random Walk mit bedingten\nWahrscheinlichkeiten 1/2 und Knotenwerten.<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Beschränkte Stoppzeiten<\/h2>\n<p>Eine ganzzahlige Zufallszeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mi>…<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>∪<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>∞<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\tau\\in\\{0,1,\\ldots\\}\\cup\\{\\infty\\}<\/annotation><\/semantics><\/math>\nist eine Stoppzeit, wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>τ<\/mi><mo>≤<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>∈<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\{\\tau\\le n\\}\\in\\mathcal F_n<\/annotation><\/semantics><\/math>\nfür jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>.\nMan kann also im Zeitpunkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nfeststellen, ob bereits gestoppt wurde. Erster Eintritt in eine\nbeobachtbare Menge ist eine Stoppzeit; der letzte positive Schritt vor\neinem festen Endzeitpunkt im Allgemeinen nicht.<\/p>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>≤<\/mo><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau\\le N<\/annotation><\/semantics><\/math>\nfast sicher. Dann gilt für ein Martingal<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M<\/mi><mi>τ<\/mi><\/msub><mo>=<\/mo><msub><mi>M<\/mi><mn>0<\/mn><\/msub><mo>+<\/mo><munderover><mo>∑<\/mo><mrow><mi>k<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>N<\/mi><\/munderover><msub><mn mathvariant=\"bold\">𝟏<\/mn><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>τ<\/mi><mo>≥<\/mo><mi>k<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>M<\/mi><mi>k<\/mi><\/msub><mo>−<\/mo><msub><mi>M<\/mi><mrow><mi>k<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">M_\\tau=M_0+\\sum_{k=1}^N\\mathbf 1_{\\{\\tau\\ge k\\}}(M_k-M_{k-1}).<\/annotation><\/semantics><\/math><\/p>\n<p>Der Indikator ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">ℱ<\/mi><mrow><mi>k<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/msub><annotation encoding=\"application/x-tex\">\\mathcal F_{k-1}<\/annotation><\/semantics><\/math>-messbar,\nda\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>τ<\/mi><mo>≥<\/mo><mi>k<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>τ<\/mi><mo>≤<\/mo><mi>k<\/mi><mo>−<\/mo><mn>1<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mi>c<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\{\\tau\\ge k\\}=\\{\\tau\\le k-1\\}^c<\/annotation><\/semantics><\/math>.\nJeder Summand hat Erwartungswert null: Bedinge auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">ℱ<\/mi><mrow><mi>k<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/msub><annotation encoding=\"application/x-tex\">\\mathcal F_{k-1}<\/annotation><\/semantics><\/math>\nund nutze die Martingaleigenschaft. Damit folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>M<\/mi><mi>τ<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>M<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[M_\\tau]=E[M_0]<\/annotation><\/semantics><\/math>.\nAnalog ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>M<\/mi><mrow><mi>n<\/mi><mo>∧<\/mo><mi>τ<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">M_{n\\wedge\\tau}<\/annotation><\/semantics><\/math>\nein Martingal, auch bei unbeschränktem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>τ<\/mi><annotation encoding=\"application/x-tex\">\\tau<\/annotation><\/semantics><\/math>,\nweil sein Zuwachs der entsprechende indikatorgewichtete Zuwachs von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>M<\/mi><annotation encoding=\"application/x-tex\">M<\/annotation><\/semantics><\/math>\nist. Die Endlichkeit von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nvermeidet einen unzulässigen Tausch von Grenzwert und Erwartung.<\/p>\n<p>Beispiel: Stoppe den symmetrischen Random Walk spätestens nach zwei\nSchritten oder beim ersten Erreichen von 1. Der Wert 1 tritt mit\nWahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>\nauf, 0 und −2 mit je\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/4<\/annotation><\/semantics><\/math>.\nSomit ist der Erwartungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>−<\/mo><mn>2<\/mn><mi>/<\/mi><mn>4<\/mn><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2-2/4=0<\/annotation><\/semantics><\/math>.\nDie Endverteilung ist nicht symmetrisch, obwohl der Mittelwert erhalten\nbleibt.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Exakte Enumeration und Grenzen<\/h2>\n<p>Die folgende exakte Enumeration verwendet gleichwahrscheinliche\nvollständige Pfade. Auch wenn ein Pfad früher stoppt, zählen seine\nFortsetzungen weiter als verschiedene Ergebnisse; dadurch entstehen die\nkorrekten Wahrscheinlichkeiten ohne doppelte Gewichtung.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> itertools <span class=\"im\">import<\/span> product<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> fractions <span class=\"im\">import<\/span> Fraction<\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> stopped_walk(steps, level):<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    s <span class=\"op\">=<\/span> <span class=\"dv\">0<\/span><\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">for<\/span> k, x <span class=\"kw\">in<\/span> <span class=\"bu\">enumerate<\/span>(steps, <span class=\"dv\">1<\/span>):<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        s <span class=\"op\">+=<\/span> x<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">if<\/span> s <span class=\"op\">&gt;=<\/span> level:<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>            <span class=\"cf\">return<\/span> k, s<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> <span class=\"bu\">len<\/span>(steps), s<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> exact_stopped_mean(n, level):<\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    paths <span class=\"op\">=<\/span> product((<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>, <span class=\"dv\">1<\/span>), repeat<span class=\"op\">=<\/span>n)<\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> Fraction(<span class=\"bu\">sum<\/span>(stopped_walk(p, level)[<span class=\"dv\">1<\/span>]<\/span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                        <span class=\"cf\">for<\/span> p <span class=\"kw\">in<\/span> paths), <span class=\"dv\">2<\/span><span class=\"op\">**<\/span>n)<\/span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">assert<\/span> exact_stopped_mean(<span class=\"dv\">8<\/span>, <span class=\"dv\">2<\/span>) <span class=\"op\">==<\/span> <span class=\"dv\">0<\/span><\/span><\/code><\/pre><\/div>\n<p>Die Laufzeit wächst exponentiell in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>;\ndie Rechnung eignet sich für kleine Horizonte. Ein alternativer Nachweis\nverwendet eine Zustandsverteilung mit absorbierten Zuständen. Die\nBeschränktheit ist substanziell: Für eine symmetrische Zufallsbewegung\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">inf<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>n<\/mi><mo>:<\/mo><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\tau=\\inf\\{n:S_n=1\\}<\/annotation><\/semantics><\/math>\nfast sicher endlich, aber\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>τ<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_\\tau=1<\/annotation><\/semantics><\/math>.\nZum Beweis der fast sicheren Endlichkeit betrachte den ersten Eintritt\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>−<\/mi><mi>a<\/mi><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\{-a,1\\}<\/annotation><\/semantics><\/math>\nfür ganze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>≥<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a\\ge1<\/annotation><\/semantics><\/math>.\nDieser Eintritt ist fast sicher endlich, denn in Blöcken von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a+1<\/annotation><\/semantics><\/math>\nSchritten führt eine Folge ausschließlich positiver Schritte sicher zum\nAustritt, falls noch nicht gestoppt wurde. Die gestoppten Werte liegen\nzwischen −a und 1. Wende den beschränkten Satz auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>τ<\/mi><mi>a<\/mi><\/msub><mo>∧<\/mo><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau_a\\wedge N<\/annotation><\/semantics><\/math>\nan und lasse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>→<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">N\\to\\infty<\/annotation><\/semantics><\/math>\nmittels dominierter Konvergenz. Aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>=<\/mo><mi>p<\/mi><mo>⋅<\/mo><mn>1<\/mn><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mi>a<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">0=p\\cdot1+(1-p)(-a)<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mi>a<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">p=a/(a+1)<\/annotation><\/semantics><\/math>.\nDie Wahrscheinlichkeit, jemals 1 zu erreichen, ist mindestens\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nfür jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a<\/mi><annotation encoding=\"application/x-tex\">a<\/annotation><\/semantics><\/math>,\nalso 1. Dennoch ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>S<\/mi><mi>τ<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>1<\/mn><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[S_\\tau]=1\\ne0<\/annotation><\/semantics><\/math>.\nDie gestoppten Werte sind hier nicht durch eine gemeinsame integrierbare\nSchranke kontrolliert; der Grenzübergang aus beschränkten Zeiten ist\nnicht gerechtfertigt.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Auf vier gleichwahrscheinlichen Ergebnissen habe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>\ndie Werte −2, 6, 4, 8. Berechne die bedingte Erwartung für die Partition\nin die ersten zwei und letzten zwei Ergebnisse sowie ihren\nMittelwert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Zeige, dass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>S<\/mi><mi>n<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">S_n^2-n<\/annotation><\/semantics><\/math>\nein Martingal für den oben definierten Random Walk ist.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ist der erste Zeitpunkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo>≥<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_n\\ge2<\/annotation><\/semantics><\/math>\neine Stoppzeit? Ist der letzte Zeitpunkt mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo>≥<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S_n\\ge2<\/annotation><\/semantics><\/math>\nvor dem festen Horizont 10 (mit Standardwert 0, wenn keiner existiert)\neine Stoppzeit?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Stoppe den Random Walk beim ersten Erreichen von 1 oder spätestens\nnach drei Schritten. Ermittle die Endverteilung und den\nErwartungswert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Warum kann man den Satz für beschränkte Stoppzeiten nicht allein\naufgrund fast sicherer Endlichkeit auf beliebige Stoppzeiten\nübertragen?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Die Zellenmittel sind 2 und 6; die bedingte Zufallsvariable hat\nErwartung 4.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bedingung auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\mathcal F_n<\/annotation><\/semantics><\/math>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>X<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[X_{n+1}]=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>X<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><mn>2<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[X_{n+1}^2]=1<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>S<\/mi><mrow><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><mn>2<\/mn><\/msubsup><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msubsup><mi>S<\/mi><mi>n<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[S_{n+1}^2-(n+1)\\mid\\mathcal F_n]=S_n^2-n<\/annotation><\/semantics><\/math>;\nAdaptivität und Integrabilität folgen aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>S<\/mi><mi>n<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|S_n|\\le n<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Ja:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mi>τ<\/mi><mo>≤<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">}<\/mo><mo>=<\/mo><msub><mo>⋃<\/mo><mrow><mi>j<\/mi><mo>≤<\/mo><mi>n<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">{<\/mo><msub><mi>S<\/mi><mi>j<\/mi><\/msub><mo>≥<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\{\\tau\\le n\\}=\\bigcup_{j\\le n}\\{S_j\\ge2\\}<\/annotation><\/semantics><\/math>.\nNein: Nach zwei positiven Schritten können spätere Schritte einen\nweiteren Besuch erzeugen oder vollständig unter 2 bleiben; ob der letzte\nBesuch bei 2 liegt, ist zu diesem Zeitpunkt nicht entscheidbar.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Die Wege beginnen entweder mit +1 (Wert 1, Wahrscheinlichkeit 1/2),\noder mit −1. Von diesen erreichen −++ den Wert 1 (1/8), −+− und −−+ den\nWert −1 (je 1/8), −−− den Wert −3 (1/8). Insgesamt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>5<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(1)=5/8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(-1)=1/4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(-3)=1/8<\/annotation><\/semantics><\/math>;\nErwartung 0.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Weil fast sichere Konvergenz nicht automatisch\nErwartungswertkonvergenz impliziert. Die erste Treffzeit von 1 liefert\nden Gegenbeweis; zusätzliche Voraussetzungen wie geeignete dominierende\nSchranken sind erforderlich.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.maths.dur.ac.uk/users/ellen.g.powell/SPnotes.html\">Ellen\nG. Powell, Stochastic Processes, Durham University<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §4.1–4.4 ·\nZuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M9-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M9-L2 – Brownsche Bewegung und quadratische Variation<\/h1>\n<p><strong>Kursbereich:<\/strong> M9 – Stochastik, Finanz- und Versicherungsmathematik<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M9&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M9-L1<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Bachelor-Vertiefung und Brücke zum\nMaster<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du charakterisierst eine Standard-Brownsche Bewegung durch ihre\nZuwächse und Stetigkeit, leitest ihre Kovarianz und Skalierung her und\nbeweist die quadratische Variation entlang deterministischer Partitionen\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>L<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">L^2<\/annotation><\/semantics><\/math>.\nDu unterscheidest Pfadeigenschaften von Verteilungsaussagen und\nuntersuchst die Konvergenz numerisch.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Definition und Skalierung<\/h2>\n<p>Eine Standard-Brownsche Bewegung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><mi>t<\/mi><\/msub><msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi>t<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">(B_t)_{t\\ge0}<\/annotation><\/semantics><\/math>\nstartet bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">B_0=0<\/annotation><\/semantics><\/math>\nfast sicher, besitzt fast sicher stetige Pfade und unabhängige Zuwächse\nauf disjunkten Zeitintervallen. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>≤<\/mo><mi>s<\/mi><mo>&lt;<\/mo><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0\\le s&lt;t<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo>−<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo>∼<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">B_t-B_s\\sim N(0,t-s)<\/annotation><\/semantics><\/math>,\nwobei der zweite Parameter die Varianz bezeichnet. Der Zuwachs ist\nunabhängig von der natürlichen Vergangenheit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><mi>σ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><mi>u<\/mi><\/msub><mo>:<\/mo><mn>0<\/mn><mo>≤<\/mo><mi>u<\/mi><mo>≤<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal F_s=\\sigma(B_u:0\\le u\\le s)<\/annotation><\/semantics><\/math>.\nInsbesondere ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo>∼<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">B_t\\sim N(0,t)<\/annotation><\/semantics><\/math>;\ndie Werte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo>,<\/mo><msub><mi>B<\/mi><mi>t<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">B_s,B_t<\/annotation><\/semantics><\/math>\nselbst sind im Allgemeinen abhängig. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>≤<\/mo><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">s\\le t<\/annotation><\/semantics><\/math>\nfolgt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>B<\/mi><mi>s<\/mi><mn>2<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>+<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo>−<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>s<\/mi><mo>,<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[B_sB_t]=E[B_s^2]+E[B_s(B_t-B_s)]=s,<\/annotation><\/semantics><\/math><\/p>\n<p>also\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Cov<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo>,<\/mo><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">min<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo>,<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Cov}(B_s,B_t)=\\min(s,t)<\/annotation><\/semantics><\/math>.\nDie gemeinsame Verteilung endlich vieler Werte ist multivariat normal,\nda jeder Wert eine lineare Kombination unabhängiger normalverteilter\nZuwächse ist. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">c&gt;0<\/annotation><\/semantics><\/math>\nhat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>B<\/mi><mo accent=\"true\">̃<\/mo><\/mover><mi>t<\/mi><\/msub><mo>=<\/mo><msup><mi>c<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><msub><mi>B<\/mi><mrow><mi>c<\/mi><mi>t<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\widetilde B_t=c^{-1/2}B_{ct}<\/annotation><\/semantics><\/math>\nwieder die definierenden Eigenschaften: Die Zuwachsvarianz ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>c<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mi>c<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">c^{-1}c(t-s)=t-s<\/annotation><\/semantics><\/math>,\nUnabhängigkeit und Stetigkeit bleiben erhalten. Das ist eine Gleichheit\nim Gesetz, keine Gleichheit der Pfade.<\/p>\n<p>Die natürliche Zeitdiskretisierung bei Schrittweite\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\nerzeugt Zuwächse\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mi>h<\/mi><\/msqrt><msub><mi>Z<\/mi><mi>k<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt h Z_k<\/annotation><\/semantics><\/math>\nmit unabhängigen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>k<\/mi><\/msub><mo>∼<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Z_k\\sim N(0,1)<\/annotation><\/semantics><\/math>.\nAnders als ein symmetrischer Random Walk mit Schritten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>±<\/mi><msqrt><mi>h<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\pm\\sqrt h<\/annotation><\/semantics><\/math>\nliefert dies exakt die endlichdimensionalen Verteilungen der Brownschen\nBewegung auf dem Gitter. Lineare Interpolation zwischen Gitterpunkten\nist jedoch keine Brownsche Bewegung.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quadratische Variation und Konvergenz<\/h2>\n<p>Für eine deterministische Partition\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>=<\/mo><msub><mi>t<\/mi><mn>0<\/mn><\/msub><mo>&lt;<\/mo><mi>⋯<\/mi><mo>&lt;<\/mo><msub><mi>t<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\pi=(0=t_0&lt;\\cdots&lt;t_n=T)<\/annotation><\/semantics><\/math>\nsetze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>h<\/mi><mi>j<\/mi><\/msub><mo>=<\/mo><msub><mi>t<\/mi><mi>j<\/mi><\/msub><mo>−<\/mo><msub><mi>t<\/mi><mrow><mi>j<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">h_j=t_j-t_{j-1}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>π<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><msub><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mi>j<\/mi><\/msub><msub><mi>h<\/mi><mi>j<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">|\\pi|=\\max_j h_j<\/annotation><\/semantics><\/math>\nund<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Q<\/mi><mi>π<\/mi><\/msub><mo>=<\/mo><munderover><mo>∑<\/mo><mrow><mi>j<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/munderover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><msub><mi>t<\/mi><mi>j<\/mi><\/msub><\/msub><mo>−<\/mo><msub><mi>B<\/mi><msub><mi>t<\/mi><mrow><mi>j<\/mi><mo>−<\/mo><mn>1<\/mn><\/mrow><\/msub><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Q_\\pi=\\sum_{j=1}^n(B_{t_j}-B_{t_{j-1}})^2.<\/annotation><\/semantics><\/math><\/p>\n<p>Da ein normalverteilter Zuwachs mit Varianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>h<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">h_j<\/annotation><\/semantics><\/math>\ndas zweite Moment\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>h<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">h_j<\/annotation><\/semantics><\/math>\nund das vierte Moment\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><msubsup><mi>h<\/mi><mi>j<\/mi><mn>2<\/mn><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">3h_j^2<\/annotation><\/semantics><\/math>\nbesitzt, hat sein Quadrat Varianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><msubsup><mi>h<\/mi><mi>j<\/mi><mn>2<\/mn><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">2h_j^2<\/annotation><\/semantics><\/math>.\nDie vierte Standardnormal-Momentformel folgt etwa durch partielle\nIntegration mit der Normaldichte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>ϕ<\/mi><mo>′<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>−<\/mi><mi>z<\/mi><mi>ϕ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\phi&#39;(z)=-z\\phi(z)<\/annotation><\/semantics><\/math>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>Z<\/mi><mn>4<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>3<\/mn><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>Z<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[Z^4]=3E[Z^2]=3<\/annotation><\/semantics><\/math>.\nWegen unabhängiger Zuwächse addieren sich die Varianzen ihrer Quadrate.\nSomit<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>Q<\/mi><mi>π<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>T<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>Q<\/mi><mi>π<\/mi><\/msub><mo>−<\/mo><mi>T<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>2<\/mn><munder><mo>∑<\/mo><mi>j<\/mi><\/munder><msubsup><mi>h<\/mi><mi>j<\/mi><mn>2<\/mn><\/msubsup><mo>≤<\/mo><mn>2<\/mn><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>π<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[Q_\\pi]=T,\\qquad E[(Q_\\pi-T)^2]=2\\sum_jh_j^2\\le2T|\\pi|.<\/annotation><\/semantics><\/math><\/p>\n<p>Für jede Folge deterministischer Partitionen mit Maschenweite gegen\nnull konvergiert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>Q<\/mi><mi>π<\/mi><\/msub><annotation encoding=\"application/x-tex\">Q_\\pi<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>L<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">L^2<\/annotation><\/semantics><\/math>\nund daher in Wahrscheinlichkeit gegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>.\nAuf äquidistanten Gittern mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nIntervallen gilt exakt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><msup><mi>T<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(Q)=2T^2/n<\/annotation><\/semantics><\/math>;\nferner\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mi>Q<\/mi><mi>/<\/mi><mi>T<\/mi><mo>∼<\/mo><msubsup><mi>χ<\/mi><mi>n<\/mi><mn>2<\/mn><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">nQ/T\\sim\\chi_n^2<\/annotation><\/semantics><\/math>.\nFür die dyadischen Partitionen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><msup><mn>2<\/mn><mi>k<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">n=2^k<\/annotation><\/semantics><\/math>\ngilt für jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϵ<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\epsilon&gt;0<\/annotation><\/semantics><\/math>\nnach Tschebyscheff<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><munder><mo>∑<\/mo><mrow><mi>k<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><\/munder><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>Q<\/mi><mi>k<\/mi><\/msub><mo>−<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>&gt;<\/mo><mi>ϵ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≤<\/mo><mfrac><mrow><mn>2<\/mn><msup><mi>T<\/mi><mn>2<\/mn><\/msup><\/mrow><msup><mi>ϵ<\/mi><mn>2<\/mn><\/msup><\/mfrac><munder><mo>∑<\/mo><mrow><mi>k<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><\/munder><msup><mn>2<\/mn><mrow><mi>−<\/mi><mi>k<\/mi><\/mrow><\/msup><mo>&lt;<\/mo><mi>∞<\/mi><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sum_{k\\ge0}P(|Q_k-T|&gt;\\epsilon)\\le \\frac{2T^2}{\\epsilon^2}\\sum_{k\\ge0}2^{-k}&lt;\\infty.<\/annotation><\/semantics><\/math><\/p>\n<p>Das erste Borel–Cantelli-Lemma (keine Unabhängigkeit der Ereignisse\nnötig) zeigt, dass nur endlich viele dieser Abweichungen eintreten.\nDurch die abzählbare Wahl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϵ<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mi>m<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\epsilon=1/m<\/annotation><\/semantics><\/math>\nfolgt fast sichere Konvergenz entlang dieser Gitter für festes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>.\nDies ist stärker als die Konvergenz in Wahrscheinlichkeit, aber keine\nAussage über jede beliebig pfadabhängig gewählte Partition.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_041_DE.svg\"\nalt=\"Vier simulierte Brownsche Pfade und ihre Variationssummen auf dyadischen Gittern; Referenzwert 1.\" />\n<figcaption aria-hidden=\"true\">Vier simulierte Brownsche Pfade und ihre\nVariationssummen auf dyadischen Gittern; Referenzwert 1.<\/figcaption>\n<\/figure>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Pfadregularität und Martingale<\/h2>\n<p>Für eine stetig differenzierbare Funktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,T]<\/annotation><\/semantics><\/math>\ngilt mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mo>′<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">C=\\max|f&#39;|<\/annotation><\/semantics><\/math>\ndie Abschätzung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>f<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>≤<\/mo><msup><mi>C<\/mi><mn>2<\/mn><\/msup><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>π<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sum(\\Delta f)^2\\le C^2T|\\pi|\\to0<\/annotation><\/semantics><\/math>.\nAllgemeiner gilt für einen stetigen Pfad endlicher Totalvariation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>V<\/mi><annotation encoding=\"application/x-tex\">V<\/annotation><\/semantics><\/math>\ndie Schranke\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>f<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>≤<\/mo><mi>V<\/mi><msub><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>f<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sum(\\Delta f)^2\\le V\\max_j|\\Delta f_j|\\to0<\/annotation><\/semantics><\/math>\ndurch gleichmäßige Stetigkeit. Da die Brownsche Bewegung entlang\ndyadischer Gitter auf jedem festen Intervall positiver Länge fast sicher\npositive quadratische Variation besitzt (derselbe Beweis mit\nverschobenem Anfang), hat sie dort fast sicher unendliche\nTotalvariation. Durch Betrachtung aller rationalen Teilintervalle gilt\ndies gleichzeitig auf jedem nichttrivialen Intervall. Insbesondere ist\nkein Teilintervall ein stetig differenzierbarer Pfad. Die stärkere\nAussage, dass Brownsche Pfade fast sicher nirgends differenzierbar sind,\nerfordert einen weiteren Beweis; sie folgt nicht allein aus unendlicher\nTotalvariation.<\/p>\n<p>Bezüglich der natürlichen Filtration sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>B<\/mi><mi>t<\/mi><\/msub><annotation encoding=\"application/x-tex\">B_t<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B_t^2-t<\/annotation><\/semantics><\/math>\nMartingale:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">E[B_t\\mid\\mathcal F_s]=B_s<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msubsup><mi>B<\/mi><mi>s<\/mi><mn>2<\/mn><\/msubsup><mo>+<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[B_t^2\\mid\\mathcal F_s]=B_s^2+t-s<\/annotation><\/semantics><\/math>.\nDamit liefert der deterministische Term\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>t<\/mi><annotation encoding=\"application/x-tex\">t<\/annotation><\/semantics><\/math>\ngenau die Kompensation der erwarteten quadratischen Zuwächse. Dies\nbereitet die Itô-Formel vor. Die Schreibweise\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>d<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mi>d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">(dB_t)^2=dt<\/annotation><\/semantics><\/math>\nist dafür eine symbolische Merkhilfe, keine Gleichung gewöhnlicher\nDifferentiale oder einzelner endlicher Zuwächse.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Reproduzierbare Simulation<\/h2>\n<p>Im folgenden Code werden zuerst feine Pfade simuliert. Gröbere Gitter\nentstehen durch Teilabtastung derselben Pfade. Das ist für eine\npfadbezogene Konvergenzbeobachtung wichtig: neue unabhängige Pfade bei\njedem Gitter würden zwar die Randverteilungen korrekt wiedergeben, aber\nkeine Annäherung entlang eines gemeinsamen Pfades zeigen.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">import<\/span> numpy <span class=\"im\">as<\/span> np<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> brownian_grid(T, m, paths<span class=\"op\">=<\/span><span class=\"dv\">1<\/span>, seed<span class=\"op\">=<\/span><span class=\"dv\">42<\/span>):<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> T <span class=\"op\">&lt;=<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> m <span class=\"op\">&lt;<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> paths <span class=\"op\">&lt;<\/span> <span class=\"dv\">1<\/span>:<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;positive T and paths, nonnegative m&quot;<\/span>)<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    rng <span class=\"op\">=<\/span> np.random.default_rng(seed)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    n <span class=\"op\">=<\/span> <span class=\"dv\">2<\/span><span class=\"op\">**<\/span>m<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    increments <span class=\"op\">=<\/span> rng.normal(<span class=\"dv\">0<\/span>, np.sqrt(T<span class=\"op\">/<\/span>n), (paths, n))<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> np.column_stack((np.zeros(paths),<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                            np.cumsum(increments, axis<span class=\"op\">=<\/span><span class=\"dv\">1<\/span>)))<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> qv_at_level(grid, k):<\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    n <span class=\"op\">=<\/span> grid.shape[<span class=\"dv\">1<\/span>] <span class=\"op\">-<\/span> <span class=\"dv\">1<\/span><\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> n <span class=\"op\">&lt;<\/span> <span class=\"dv\">1<\/span> <span class=\"kw\">or<\/span> n <span class=\"op\">&amp;<\/span> (n<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>) <span class=\"kw\">or<\/span> <span class=\"kw\">not<\/span> <span class=\"dv\">0<\/span> <span class=\"op\">&lt;=<\/span> k <span class=\"op\">&lt;=<\/span> n.bit_length()<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>:<\/span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;invalid dyadic grid or level&quot;<\/span>)<\/span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    step <span class=\"op\">=<\/span> n <span class=\"op\">//<\/span> <span class=\"dv\">2<\/span><span class=\"op\">**<\/span>k<\/span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> np.<span class=\"bu\">sum<\/span>(np.diff(grid[:, ::step], axis<span class=\"op\">=<\/span><span class=\"dv\">1<\/span>)<span class=\"op\">**<\/span><span class=\"dv\">2<\/span>, axis<span class=\"op\">=<\/span><span class=\"dv\">1<\/span>)<\/span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>grid <span class=\"op\">=<\/span> brownian_grid(<span class=\"dv\">1<\/span>, <span class=\"dv\">10<\/span>, paths<span class=\"op\">=<\/span><span class=\"dv\">2000<\/span>)<\/span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"cf\">for<\/span> k <span class=\"kw\">in<\/span> (<span class=\"dv\">2<\/span>, <span class=\"dv\">5<\/span>, <span class=\"dv\">8<\/span>, <span class=\"dv\">10<\/span>):<\/span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    q <span class=\"op\">=<\/span> qv_at_level(grid, k)<\/span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"bu\">print<\/span>(k, q.mean(), q.var(), <span class=\"dv\">2<\/span><span class=\"op\">/<\/span><span class=\"dv\">2<\/span><span class=\"op\">**<\/span>k)<\/span><\/code><\/pre><\/div>\n<p>Die vier Ausgaben enthalten Gitterstufe, empirischen Mittelwert,\nempirische Varianz (mit Divisor Anzahl der Pfade) und theoretische\nVarianz. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T=1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k=5<\/annotation><\/semantics><\/math>\nist die theoretische Varianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/16<\/annotation><\/semantics><\/math>,\ndie Standardabweichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/4<\/annotation><\/semantics><\/math>;\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k=10<\/annotation><\/semantics><\/math>\nbeträgt die Varianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>512<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/512<\/annotation><\/semantics><\/math>.\nEin einzelnes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>Q<\/mi><mi>k<\/mi><\/msub><annotation encoding=\"application/x-tex\">Q_k<\/annotation><\/semantics><\/math>\nmuss nicht monoton gegen 1 konvergieren. Zufallszahlen sind\npseudorandomisiert, und Rundung sowie endliche Stichprobengröße\nbegrenzen die Genauigkeit. Eine Simulation belegt keine fast sichere\nAussage. Speicherbedarf wächst mit Anzahl der Pfade mal Gittergröße; für\ngroße Experimente sollten Pfade blockweise erzeugt werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne die Verteilung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>B<\/mi><mn>5<\/mn><\/msub><mo>−<\/mo><msub><mi>B<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">B_5-B_2<\/annotation><\/semantics><\/math>\nund die Kovarianz von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>B<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">B_2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>B<\/mi><mn>5<\/mn><\/msub><annotation encoding=\"application/x-tex\">B_5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Zeige, dass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><msub><mi>B<\/mi><mrow><mn>4<\/mn><mi>t<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\tfrac12 B_{4t}<\/annotation><\/semantics><\/math>\neine Standard-Brownsche Bewegung ist.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Berechne für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T=2<\/annotation><\/semantics><\/math>\nund 128 äquidistante Intervalle Erwartung und Varianz der quadratischen\nVariationssumme.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Beweise, dass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>t<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f(t)=t^2<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[0,1]<\/annotation><\/semantics><\/math>\nquadratische Variation null besitzt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Zeige mit bedingter Erwartung, dass\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B_t^2-t<\/annotation><\/semantics><\/math>\nein Martingal ist, und erkläre, warum\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><annotation encoding=\"application/x-tex\">B_t^2<\/annotation><\/semantics><\/math>\nkeines ist.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">N(0,3)<\/annotation><\/semantics><\/math>\nmit Varianz 3; Kovarianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">min<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\min(2,5)=2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Die Zuwachsvarianz ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>4<\/mn><\/mfrac><\/mstyle><mo>⋅<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tfrac14\\cdot4(t-s)=t-s<\/annotation><\/semantics><\/math>;\nStartwert, Unabhängigkeit, Normalverteilung und Stetigkeit bleiben\nerhalten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[Q]=2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>Q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mo>⋅<\/mo><mn>4<\/mn><mi>/<\/mi><mn>128<\/mn><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(Q)=2\\cdot4/128=1/16<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi>f<\/mi><mo>′<\/mo><\/msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|f&#39;|\\le2<\/annotation><\/semantics><\/math>,\ndaher\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>f<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>≤<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>π<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sum(\\Delta f)^2\\le4|\\pi|\\to0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Aus unabhängigen Zuwächsen folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>t<\/mi><mo>∣<\/mo><msub><mi mathvariant=\"script\">ℱ<\/mi><mi>s<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msubsup><mi>B<\/mi><mi>s<\/mi><mn>2<\/mn><\/msubsup><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>t<\/mi><mo>=<\/mo><msubsup><mi>B<\/mi><mi>s<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[B_t^2-t\\mid\\mathcal F_s]=B_s^2+(t-s)-t=B_s^2-s<\/annotation><\/semantics><\/math>.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><annotation encoding=\"application/x-tex\">B_t^2<\/annotation><\/semantics><\/math>\nhat den zeitabhängigen Erwartungswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>t<\/mi><annotation encoding=\"application/x-tex\">t<\/annotation><\/semantics><\/math>\nund ist deshalb kein Martingal.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://lorenzonaranjo.com/class-materials/stochastic-processes/notes/brownian-motion.html\">Lorenzo\nNaranjo, Stochastic Foundations for Finance: Brownian Motion<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> ·\nBrownian Motion; Quadratic Variation of Brownian Motion · Zuletzt\nabgerufen: 2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M9-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M9-L3 – Itô-Formel und stochastische Differentialgleichungen<\/h1>\n<p><strong>Kursbereich:<\/strong> M9 – Stochastik, Finanz- und Versicherungsmathematik<\/p>\n<p><strong>Niveau:<\/strong> Master · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M9&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M9-L2<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L4<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Master-Vertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du leitest die Itô-Korrektur für das Quadrat einer Brownschen\nBewegung aus endlichen Summen her, formulierst die allgemeine Itô-Regel\nunter geeigneten Voraussetzungen und konstruierst die Lösung einer\ngeometrischen Brownschen Bewegung. Du unterscheidest Drift, Diffusion\nund Diskretisierungsfehler.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Vom Gitter zum Itô-Integral<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>B<\/mi><annotation encoding=\"application/x-tex\">B<\/annotation><\/semantics><\/math>\neine Standard-Brownsche Bewegung mit ihrer natürlichen Filtration. Für\nein adaptiertes stückweise konstantes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><msub><mi>H<\/mi><mi>j<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">H_s=H_j<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>t<\/mi><mi>j<\/mi><\/msub><mo>,<\/mo><msub><mi>t<\/mi><mrow><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">[t_j,t_{j+1})<\/annotation><\/semantics><\/math>,\nwobei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>H<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">H_j<\/annotation><\/semantics><\/math>\nquadratintegrierbar und zur Zeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>t<\/mi><mi>j<\/mi><\/msub><annotation encoding=\"application/x-tex\">t_j<\/annotation><\/semantics><\/math>\nmessbar ist, definiert man<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>H<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><munder><mo>∑<\/mo><mi>j<\/mi><\/munder><msub><mi>H<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><msub><mi>t<\/mi><mrow><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><\/msub><mo>−<\/mo><msub><mi>B<\/mi><msub><mi>t<\/mi><mi>j<\/mi><\/msub><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I(H)=\\sum_j H_j(B_{t_{j+1}}-B_{t_j}).<\/annotation><\/semantics><\/math><\/p>\n<p>Die Zuwächse haben bedingt auf die Vergangenheit Mittelwert null und\nVarianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>h<\/mi><mi>j<\/mi><\/msub><mo>=<\/mo><msub><mi>t<\/mi><mrow><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><mo>−<\/mo><msub><mi>t<\/mi><mi>j<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">h_j=t_{j+1}-t_j<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>i<\/mi><mo>&lt;<\/mo><mi>j<\/mi><\/mrow><annotation encoding=\"application/x-tex\">i&lt;j<\/annotation><\/semantics><\/math>\nverschwindet der gemischte Erwartungswert durch Konditionieren auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi mathvariant=\"script\">ℱ<\/mi><msub><mi>t<\/mi><mi>j<\/mi><\/msub><\/msub><annotation encoding=\"application/x-tex\">\\mathcal F_{t_j}<\/annotation><\/semantics><\/math>.\nDamit gelten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>I<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>H<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[I(H)]=0<\/annotation><\/semantics><\/math>\nund die Itô-Isometrie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>I<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>H<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mo>∑<\/mo><mi>j<\/mi><\/msub><msub><mi>h<\/mi><mi>j<\/mi><\/msub><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>H<\/mi><mi>j<\/mi><mn>2<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[I(H)^2]=\\sum_j h_jE[H_j^2]<\/annotation><\/semantics><\/math>.\nDurch stetige Fortsetzung in der Norm\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mi>H<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">∥<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mi>E<\/mi><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>T<\/mi><\/msubsup><msubsup><mi>H<\/mi><mi>s<\/mi><mn>2<\/mn><\/msubsup><mi>d<\/mi><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\|H\\|^2=E\\int_0^T H_s^2ds<\/annotation><\/semantics><\/math>\nentsteht das Integral für quadratintegrierbare vorhersehbare Prozesse.\nDie Vollständigkeits- und Approximationsdetails dieser Konstruktion\nwerden hier vorausgesetzt.<\/p>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">H_s=B_s<\/annotation><\/semantics><\/math>\napproximieren die linken Gitterwerte das Integrand in dieser Norm:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑<\/mo><mi>j<\/mi><\/msub><msubsup><mo>∫<\/mo><msub><mi>t<\/mi><mi>j<\/mi><\/msub><msub><mi>t<\/mi><mrow><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><\/msub><\/msubsup><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo>−<\/mo><msub><mi>B<\/mi><msub><mi>t<\/mi><mi>j<\/mi><\/msub><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>d<\/mi><mi>s<\/mi><mo>=<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><msub><mo>∑<\/mo><mi>j<\/mi><\/msub><msubsup><mi>h<\/mi><mi>j<\/mi><mn>2<\/mn><\/msubsup><mo>→<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sum_j\\int_{t_j}^{t_{j+1}}E[(B_s-B_{t_j})^2]ds=\\tfrac12\\sum_jh_j^2\\to0<\/annotation><\/semantics><\/math>.\nDie algebraische Identität<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>B<\/mi><mi>T<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><mn>2<\/mn><munder><mo>∑<\/mo><mi>j<\/mi><\/munder><msub><mi>B<\/mi><msub><mi>t<\/mi><mi>j<\/mi><\/msub><\/msub><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>B<\/mi><mi>j<\/mi><\/msub><mo>+<\/mo><munder><mo>∑<\/mo><mi>j<\/mi><\/munder><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>B<\/mi><mi>j<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">B_T^2=2\\sum_j B_{t_j}\\Delta B_j+\\sum_j(\\Delta B_j)^2<\/annotation><\/semantics><\/math><\/p>\n<p>und die quadratische Variation aus <a\nhref=\"index.html?course=university_mathematics&amp;module=M9&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M9-L2<\/a> liefern in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>L<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">L^2<\/annotation><\/semantics><\/math>\ndie Gleichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>B<\/mi><mi>T<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><mn>2<\/mn><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>T<\/mi><\/msubsup><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mo>+<\/mo><mi>T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">B_T^2=2\\int_0^T B_s\\,dB_s+T<\/annotation><\/semantics><\/math>.\nDie rechte Summe der Quadrate darf nicht wie bei glatten Pfaden\nweggelassen werden. Rechte statt linker Stützstellen würden hier die\nSumme um\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mo>∑<\/mo><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>B<\/mi><mi>j<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\sum_j(\\Delta B_j)^2<\/annotation><\/semantics><\/math>\nverändern; die Wahl der Stützstellen ist also wesentlich.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Itô-Formel und stochastische Differentialgleichung<\/h2>\n<p>Ein Itô-Prozess\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo>=<\/mo><msub><mi>X<\/mi><mn>0<\/mn><\/msub><mo>+<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><msub><mi>a<\/mi><mi>s<\/mi><\/msub><mi>d<\/mi><mi>s<\/mi><mo>+<\/mo><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>t<\/mi><\/msubsup><msub><mi>b<\/mi><mi>s<\/mi><\/msub><mi>d<\/mi><msub><mi>B<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">X_t=X_0+\\int_0^t a_s ds+\\int_0^t b_s dB_s<\/annotation><\/semantics><\/math>\nbenötigt adaptierte, für die Integrale geeignete Koeffizienten\n(insbesondere lokal integrierbare Drift und lokal quadratintegrierbaren\nvorhersehbaren Diffusionskoeffizienten). Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>∈<\/mo><msup><mi>C<\/mi><mrow><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f\\in C^{1,2}<\/annotation><\/semantics><\/math>,\neinmal stetig nach der Zeit und zweimal nach dem Ort differenzierbar,\nlautet die Itô-Formel lokal<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><msub><mi>f<\/mi><mi>t<\/mi><\/msub><mo>+<\/mo><msub><mi>a<\/mi><mi>t<\/mi><\/msub><msub><mi>f<\/mi><mi>x<\/mi><\/msub><mo>+<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><msubsup><mi>b<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><msub><mi>f<\/mi><mrow><mi>x<\/mi><mi>x<\/mi><\/mrow><\/msub><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>d<\/mi><mi>t<\/mi><mo>+<\/mo><msub><mi>b<\/mi><mi>t<\/mi><\/msub><msub><mi>f<\/mi><mi>x<\/mi><\/msub><mi>d<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">df(t,X_t)=\\left(f_t+a_tf_x+\\tfrac12 b_t^2 f_{xx}\\right)dt+b_tf_xdB_t.<\/annotation><\/semantics><\/math><\/p>\n<p>Die Ableitungen werden bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(t,X_t)<\/annotation><\/semantics><\/math>\nausgewertet. Der Ausdruck ist eine Kurzschreibweise für eine\nIntegralgleichung, keine Gleichung klassischer Ableitungen. Formal gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>d<\/mi><mi>B<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mi>d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">(dB)^2=dt<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>t<\/mi><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><mi>B<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>d<\/mi><mi>t<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">dt\\,dB=(dt)^2=0<\/annotation><\/semantics><\/math>.\nFür allgemeine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\nist dies nur eine Merkregel; der vollständige Satz benötigt\nGrenzwertargumente und gegebenenfalls Lokalisierung. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mi>x<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">f(x)=x^2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X<\/mi><mo>=<\/mo><mi>B<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X=B<\/annotation><\/semantics><\/math>\nwurde die Formel bereits bewiesen.<\/p>\n<p>In einer SDE\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo>=<\/mo><mi>μ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mi>t<\/mi><mo>+<\/mo><mi>σ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">dX_t=\\mu(t,X_t)dt+\\sigma(t,X_t)dB_t<\/annotation><\/semantics><\/math>\nbeschreibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>μ<\/mi><annotation encoding=\"application/x-tex\">\\mu<\/annotation><\/semantics><\/math>\ndie lokale Drift und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\sigma^2<\/annotation><\/semantics><\/math>\ndie lokale Varianzrate. Nicht jede Wahl der Koeffizienten garantiert\nExistenz und Eindeutigkeit. Globale Lipschitz-Stetigkeit im Ort und\nlineares Wachstum mit geeigneter Zeitmessbarkeit und\nquadratintegrierbarem Anfangswert sind klassische hinreichende\nBedingungen. Im folgenden linearen Beispiel sind sie erfüllt.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Geometrische Brownsche Bewegung<\/h2>\n<p>Betrachte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo>=<\/mo><mi>μ<\/mi><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mi>d<\/mi><mi>t<\/mi><mo>+<\/mo><mi>σ<\/mi><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mi>d<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">dX_t=\\mu X_tdt+\\sigma X_tdB_t<\/annotation><\/semantics><\/math>\nmit konstanten reellen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>μ<\/mi><annotation encoding=\"application/x-tex\">\\mu<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ<\/mi><mo>≥<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma\\ge0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">X_0=x_0&gt;0<\/annotation><\/semantics><\/math>.\nStatt Positivität vorab anzunehmen, konstruiere<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Y<\/mi><mi>t<\/mi><\/msub><mo>=<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>μ<\/mi><mo>−<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>t<\/mi><mo>+<\/mo><mi>σ<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Y_t=x_0\\exp((\\mu-\\sigma^2/2)t+\\sigma B_t).<\/annotation><\/semantics><\/math><\/p>\n<p>Itô auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>μ<\/mi><mo>−<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>t<\/mi><mo>+<\/mo><mi>σ<\/mi><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f(t,b)=x_0\\exp((\\mu-\\sigma^2/2)t+\\sigma b)<\/annotation><\/semantics><\/math>\nergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>t<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>μ<\/mi><mo>−<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>f<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f_t=(\\mu-\\sigma^2/2)f<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>b<\/mi><\/msub><mo>=<\/mo><mi>σ<\/mi><mi>f<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f_b=\\sigma f<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mrow><mi>b<\/mi><mi>b<\/mi><\/mrow><\/msub><mo>=<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>f<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f_{bb}=\\sigma^2 f<\/annotation><\/semantics><\/math>.\nDaher\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><msub><mi>Y<\/mi><mi>t<\/mi><\/msub><mo>=<\/mo><mi>μ<\/mi><msub><mi>Y<\/mi><mi>t<\/mi><\/msub><mi>d<\/mi><mi>t<\/mi><mo>+<\/mo><mi>σ<\/mi><msub><mi>Y<\/mi><mi>t<\/mi><\/msub><mi>d<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">dY_t=\\mu Y_tdt+\\sigma Y_tdB_t<\/annotation><\/semantics><\/math>.\nEindeutigkeit liefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X<\/mi><mo>=<\/mo><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X=Y<\/annotation><\/semantics><\/math>;\ninsbesondere ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>\npositiv. Mit der Momentenerzeugenden Funktion der Normalverteilung folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><msup><mi>e<\/mi><mrow><mi>μ<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">E[X_t]=x_0e^{\\mu t}<\/annotation><\/semantics><\/math>\nund<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mi>t<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msubsup><mi>x<\/mi><mn>0<\/mn><mn>2<\/mn><\/msubsup><msup><mi>e<\/mi><mrow><mn>2<\/mn><mi>μ<\/mi><mi>t<\/mi><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msup><mi>e<\/mi><mrow><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>t<\/mi><\/mrow><\/msup><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(X_t)=x_0^2e^{2\\mu t}(e^{\\sigma^2t}-1).<\/annotation><\/semantics><\/math><\/p>\n<p>Die Logarithmusverteilung hat Mittelwert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">log<\/mi><mo>&#8289;<\/mo><\/mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>μ<\/mi><mo>−<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\log x_0+(\\mu-\\sigma^2/2)t<\/annotation><\/semantics><\/math>\nund Varianz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sigma^2t<\/annotation><\/semantics><\/math>;\nder Median des Prozesses ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><msup><mi>e<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>μ<\/mi><mo>−<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">x_0e^{(\\mu-\\sigma^2/2)t}<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mi>σ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_0=2,\\mu=0{,}2,\\sigma=0{,}4<\/annotation><\/semantics><\/math>\nbeträgt die Log-Drift\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>12<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}12<\/annotation><\/semantics><\/math>.\nMittelwert und Median sind verschieden, obwohl die Drift des Prozesses\npositiv ist. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mu=0<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>X<\/mi><annotation encoding=\"application/x-tex\">X<\/annotation><\/semantics><\/math>\nein Martingal, denn der Exponentialfaktor des unabhängigen Zuwachses hat\nbedingten Mittelwert eins.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_042_DE.svg\"\nalt=\"Geometrische Brownsche Bewegung: vier simulierte Pfade, theoretischer Mittelwert und Median; exakter und Euler-Pfad mit gleichen Zuwächsen.\" />\n<figcaption aria-hidden=\"true\">Geometrische Brownsche Bewegung: vier\nsimulierte Pfade, theoretischer Mittelwert und Median; exakter und\nEuler-Pfad mit gleichen Zuwächsen.<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Simulation und Euler–Maruyama<\/h2>\n<p>Für äquidistante Gitter mit Schritt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>h<\/mi><annotation encoding=\"application/x-tex\">h<\/annotation><\/semantics><\/math>\nwird\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>X<\/mi><mrow><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><\/mrow><mrow><mi>E<\/mi><mi>M<\/mi><\/mrow><\/msubsup><mo>=<\/mo><msubsup><mi>X<\/mi><mi>j<\/mi><mrow><mi>E<\/mi><mi>M<\/mi><\/mrow><\/msubsup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>+<\/mo><mi>μ<\/mi><mi>h<\/mi><mo>+<\/mo><mi>σ<\/mi><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>B<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">X_{j+1}^{EM}=X_j^{EM}(1+\\mu h+\\sigma\\Delta B_j)<\/annotation><\/semantics><\/math>\nverwendet. Die exakte Gitterlösung multipliziert dagegen mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>μ<\/mi><mo>−<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>h<\/mi><mo>+<\/mo><mi>σ<\/mi><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>B<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\exp((\\mu-\\sigma^2/2)h+\\sigma\\Delta B_j)<\/annotation><\/semantics><\/math>.\nDie gleichen Zuwächse in beiden Verfahren erlauben einen pfadweisen\nVergleich;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>B<\/mi><mi>j<\/mi><\/msub><mo>∼<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mi>h<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Delta B_j\\sim N(0,h)<\/annotation><\/semantics><\/math>.\nEuler kann negative Werte erzeugen, die exakte Lösung nicht. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma&gt;0<\/annotation><\/semantics><\/math>\nbesitzt der Euler-Faktor für jedes\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h&gt;0<\/annotation><\/semantics><\/math>\neine positive Wahrscheinlichkeit, negativ zu sein. Für diese SDE\nkonvergiert Euler–Maruyama im quadratischen Mittel mit starker Ordnung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>\n(allgemeiner Konvergenzsatz, hier nicht bewiesen). Eine einzelne\nSimulation belegt diese Ordnung nicht. Der Code erwartet bereits\nskalierte Zuwächse; er ist ein Lehrmodell, keine Prognose realer\nMarktpreise.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">import<\/span> numpy <span class=\"im\">as<\/span> np<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> gbm_paths(x0, mu, sigma, h, increments):<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    increments <span class=\"op\">=<\/span> np.asarray(increments, dtype<span class=\"op\">=<\/span><span class=\"bu\">float<\/span>)<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> x0 <span class=\"op\">&lt;=<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> h <span class=\"op\">&lt;=<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> sigma <span class=\"op\">&lt;<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> increments.ndim <span class=\"op\">!=<\/span> <span class=\"dv\">1<\/span>:<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;invalid parameters&quot;<\/span>)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    t <span class=\"op\">=<\/span> h <span class=\"op\">*<\/span> np.arange(<span class=\"bu\">len<\/span>(increments)<span class=\"op\">+<\/span><span class=\"dv\">1<\/span>)<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    b <span class=\"op\">=<\/span> np.r_[<span class=\"fl\">0.<\/span>, np.cumsum(increments)]<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    exact <span class=\"op\">=<\/span> x0 <span class=\"op\">*<\/span> np.exp((mu<span class=\"op\">-<\/span>sigma<span class=\"op\">**<\/span><span class=\"dv\">2<\/span><span class=\"op\">/<\/span><span class=\"dv\">2<\/span>)<span class=\"op\">*<\/span>t <span class=\"op\">+<\/span> sigma<span class=\"op\">*<\/span>b)<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    euler <span class=\"op\">=<\/span> x0 <span class=\"op\">*<\/span> np.r_[<span class=\"fl\">1.<\/span>, np.cumprod(<span class=\"dv\">1<\/span><span class=\"op\">+<\/span>mu<span class=\"op\">*<\/span>h<span class=\"op\">+<\/span>sigma<span class=\"op\">*<\/span>increments)]<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> t, exact, euler<\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>rng <span class=\"op\">=<\/span> np.random.default_rng(<span class=\"dv\">41<\/span>)<\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>h <span class=\"op\">=<\/span> <span class=\"dv\">1<\/span><span class=\"op\">/<\/span><span class=\"dv\">256<\/span><\/span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>db <span class=\"op\">=<\/span> rng.normal(<span class=\"dv\">0<\/span>, np.sqrt(h), <span class=\"dv\">256<\/span>)<\/span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>t, exact, euler <span class=\"op\">=<\/span> gbm_paths(<span class=\"dv\">2<\/span>, <span class=\"fl\">.2<\/span>, <span class=\"fl\">.4<\/span>, h, db)<\/span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"bu\">print<\/span>(exact[<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>], euler[<span class=\"op\">-<\/span><span class=\"dv\">1<\/span>])<\/span><\/code><\/pre><\/div>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Leite die Itô-Isometrie für zwei unabhängige Brown-Zuwächse mit\nvorhersehbaren Integranden her.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mo>∫<\/mo><mn>0<\/mn><mi>T<\/mi><\/msubsup><msub><mi>B<\/mi><mi>s<\/mi><\/msub><mspace width=\"0.167em\"><\/mspace><mi>d<\/mi><msub><mi>B<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\int_0^T B_s\\,dB_s<\/annotation><\/semantics><\/math>\nund seinen Erwartungswert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wende die Itô-Formel auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msubsup><mi>B<\/mi><mi>t<\/mi><mn>3<\/mn><\/msubsup><annotation encoding=\"application/x-tex\">B_t^3<\/annotation><\/semantics><\/math>\nan.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Berechne Log-Drift und Median bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mi>σ<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>T<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_0=1,\\mu=0,\\sigma=1,T=2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Zeige mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>μ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mi>σ<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>B<\/mi><mo>=<\/mo><mi>−<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">h=1,\\mu=0,\\sigma=1,\\Delta B=-2<\/annotation><\/semantics><\/math>,\ndass Euler die Positivität verletzen kann.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Die gemischten Terme verschwinden durch bedingte Erwartung zum\nzweiten Startzeitpunkt. Die Diagonalterme sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>h<\/mi><mi>j<\/mi><\/msub><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>H<\/mi><mi>j<\/mi><mn>2<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">h_jE[H_j^2]<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>B<\/mi><mi>T<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><mi>T<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(B_T^2-T)/2<\/annotation><\/semantics><\/math>;\nErwartungswert null.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msubsup><mi>B<\/mi><mi>t<\/mi><mn>3<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><msubsup><mi>B<\/mi><mi>t<\/mi><mn>2<\/mn><\/msubsup><mi>d<\/mi><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mo>+<\/mo><mn>3<\/mn><msub><mi>B<\/mi><mi>t<\/mi><\/msub><mi>d<\/mi><mi>t<\/mi><\/mrow><annotation encoding=\"application/x-tex\">d(B_t^3)=3B_t^2dB_t+3B_tdt<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Log-Drift\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1/2<\/annotation><\/semantics><\/math>,\nMedian\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">e^{-1}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Euler-Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1<\/annotation><\/semantics><\/math>,\nexakter Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>5<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e^{-5/2}&gt;0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://ocw.mit.edu/courses/18-642-topics-in-mathematics-with-applications-in-finance-fall-2024/mit18_642_f24_lec19_1.pdf\">MIT\nOpenCourseWare, 18.642: Stochastic Calculus<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · S. 21–23 (PDF-Text)\n(Prüfumfang: Text) · Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft:\n2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M9-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M9-L4 – Arbitragefreie Bewertung im Binomialmodell<\/h1>\n<p><strong>Kursbereich:<\/strong> M9 – Stochastik, Finanz- und Versicherungsmathematik<\/p>\n<p><strong>Niveau:<\/strong> Master · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L7<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M9&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M9-L1<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Master-Vertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du prüfst Arbitragefreiheit im Einperiodenmodell, leitest das\neindeutige replizierende Portfolio und die risikoneutrale Bewertung her\nund wendest sie auf einen selbst konstruierten Optionsanspruch an. Du\ntrennst Modellwahrscheinlichkeit, Bewertung und reale Risiken.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Marktmodell und Arbitrage<\/h2>\n<p>Zum Zeitpunkt 0 kostet eine Aktie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s&gt;0<\/annotation><\/semantics><\/math>,\nzum Zeitpunkt 1 ist sie entweder\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">su<\/annotation><\/semantics><\/math>\noder\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>d<\/mi><\/mrow><annotation encoding=\"application/x-tex\">sd<\/annotation><\/semantics><\/math>\nwert, mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u<\/mi><mo>&gt;<\/mo><mi>d<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u&gt;d&gt;0<\/annotation><\/semantics><\/math>.\nBeide Zustände besitzen positive tatsächliche Wahrscheinlichkeit. Ein\nGeldkonto wächst pro Periode um den Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R&gt;0<\/annotation><\/semantics><\/math>,\nd. h. ein Anfangsbetrag\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>c<\/mi><annotation encoding=\"application/x-tex\">c<\/annotation><\/semantics><\/math>\nwird zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Rc<\/annotation><\/semantics><\/math>.\nDie Periode kann beliebig lang sein;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>R<\/mi><annotation encoding=\"application/x-tex\">R<\/annotation><\/semantics><\/math>\nist kein kontinuierlicher Zinssatz. Wir erlauben beliebige reelle\nStückzahlen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Δ<\/mi><annotation encoding=\"application/x-tex\">\\Delta<\/annotation><\/semantics><\/math>\nund Kontobeträge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>c<\/mi><annotation encoding=\"application/x-tex\">c<\/annotation><\/semantics><\/math>,\nalso auch Leerverkauf und Kreditaufnahme, ohne Gebühren oder Ausfall. Es\ngibt keine Dividenden und keine weiteren Handelszeitpunkte.<\/p>\n<p>Ein Portfolio hat Anfangswert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mi>s<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">V_0=s\\Delta+c<\/annotation><\/semantics><\/math>\nund Endwerte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mi>u<\/mi><\/msub><mo>=<\/mo><mi>s<\/mi><mi>u<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>R<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">V_u=su\\Delta+Rc<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mi>d<\/mi><\/msub><mo>=<\/mo><mi>s<\/mi><mi>d<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>R<\/mi><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">V_d=sd\\Delta+Rc<\/annotation><\/semantics><\/math>.\nArbitrage bedeutet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">V_0=0<\/annotation><\/semantics><\/math>,\nbeide Endwerte nichtnegativ und wenigstens einer strikt positiv. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">V_0=0<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mi>−<\/mi><mi>s<\/mi><mi mathvariant=\"normal\">Δ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">c=-s\\Delta<\/annotation><\/semantics><\/math>,\nalso\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mi>u<\/mi><\/msub><mo>=<\/mo><mi>s<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>−<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">V_u=s\\Delta(u-R)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mi>d<\/mi><\/msub><mo>=<\/mo><mi>s<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>d<\/mi><mo>−<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">V_d=s\\Delta(d-R)<\/annotation><\/semantics><\/math>.\nWenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>&lt;<\/mo><mi>R<\/mi><mo>&lt;<\/mo><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">d&lt;R&lt;u<\/annotation><\/semantics><\/math>,\nhaben diese Werte für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\ne0<\/annotation><\/semantics><\/math>\nentgegengesetzte Vorzeichen. Ist dagegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>≤<\/mo><mi>d<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R\\le d<\/annotation><\/semantics><\/math>,\nliefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=1<\/annotation><\/semantics><\/math>\neine Arbitrage; bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>≥<\/mo><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R\\ge u<\/annotation><\/semantics><\/math>\nliefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=-1<\/annotation><\/semantics><\/math>\neine. Wegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u<\/mi><mo>&gt;<\/mo><mi>d<\/mi><\/mrow><annotation encoding=\"application/x-tex\">u&gt;d<\/annotation><\/semantics><\/math>\nist jeweils mindestens ein Endwert positiv, auch im Gleichheitsfall.\nSomit ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>&lt;<\/mo><mi>R<\/mi><mo>&lt;<\/mo><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">d&lt;R&lt;u<\/annotation><\/semantics><\/math>\ngenau die Bedingung für Arbitragefreiheit.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Replikation und eindeutiger Preis<\/h2>\n<p>Ein Anspruch auf die Endzahlungen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mi>u<\/mi><\/msub><mo>,<\/mo><msub><mi>H<\/mi><mi>d<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">H_u,H_d<\/annotation><\/semantics><\/math>\nist durch das lineare System<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>u<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>R<\/mi><mi>c<\/mi><mo>=<\/mo><msub><mi>H<\/mi><mi>u<\/mi><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>s<\/mi><mi>d<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>R<\/mi><mi>c<\/mi><mo>=<\/mo><msub><mi>H<\/mi><mi>d<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">su\\Delta+Rc=H_u,\\qquad sd\\Delta+Rc=H_d<\/annotation><\/semantics><\/math><\/p>\n<p>replizierbar. Die Differenz beider Gleichungen ergibt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mfrac><mrow><msub><mi>H<\/mi><mi>u<\/mi><\/msub><mo>−<\/mo><msub><mi>H<\/mi><mi>d<\/mi><\/msub><\/mrow><mrow><mi>s<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>−<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>c<\/mi><mo>=<\/mo><mfrac><mrow><mi>u<\/mi><msub><mi>H<\/mi><mi>d<\/mi><\/msub><mo>−<\/mo><mi>d<\/mi><msub><mi>H<\/mi><mi>u<\/mi><\/msub><\/mrow><mrow><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>−<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=\\frac{H_u-H_d}{s(u-d)},\\qquad c=\\frac{uH_d-dH_u}{R(u-d)}.<\/annotation><\/semantics><\/math><\/p>\n<p>Die Determinante ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi>R<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>−<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">sR(u-d)&gt;0<\/annotation><\/semantics><\/math>,\nalso ist jede Auszahlung in diesem Zwei-Zustands-Markt eindeutig\nreplizierbar (Vollständigkeit). Der Preis muss\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mi>s<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">H_0=s\\Delta+c<\/annotation><\/semantics><\/math>\nsein: Ist der Anspruch teurer, verkauft man ihn und erwirbt die\nReplikation; ist er billiger, kehrt man die Positionen um. Der positive\nAnfangsüberschuss wird auf dem Geldkonto angelegt, die späteren\nAnspruchszahlungen heben sich genau auf. Das beweist die Eindeutigkeit,\nsofern der Anspruch ebenfalls frei handelbar ist. Umgekehrt erzeugt der\nPreis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mo>+<\/mo><mi>c<\/mi><\/mrow><annotation encoding=\"application/x-tex\">s\\Delta+c<\/annotation><\/semantics><\/math>\nkeine neue Arbitrage, denn jede Anspruchsposition lässt sich durch ihr\nreplizierendes Portfolio ersetzen.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Risikoneutrales Maß<\/h2>\n<p>Setze\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo>−<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>u<\/mi><mo>−<\/mo><mi>d<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">q=(R-d)/(u-d)<\/annotation><\/semantics><\/math>.\nUnter strikter Arbitragefreiheit gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>q<\/mi><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0&lt;q&lt;1<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mi>u<\/mi><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>d<\/mi><mo>=<\/mo><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">qu+(1-q)d=R<\/annotation><\/semantics><\/math>.\nDamit ist der abgezinste Aktienpreis unter dem Wahrscheinlichkeitsmaß\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>Q<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>q<\/mi><mo>,<\/mo><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">Q=(q,1-q)<\/annotation><\/semantics><\/math>\nein Martingal. Dieses Maß ist wegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u<\/mi><mo>&gt;<\/mo><mi>d<\/mi><\/mrow><annotation encoding=\"application/x-tex\">u&gt;d<\/annotation><\/semantics><\/math>\neindeutig; es ist zum tatsächlichen Maß äquivalent, da beide Zustände\npositive Wahrscheinlichkeit haben. Durch Einsetzen der Portfoliowerte\nfolgt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mfrac><mrow><mi>q<\/mi><msub><mi>H<\/mi><mi>u<\/mi><\/msub><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>q<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>H<\/mi><mi>d<\/mi><\/msub><\/mrow><mi>R<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">H_0=\\frac{qH_u+(1-q)H_d}{R}.<\/annotation><\/semantics><\/math><\/p>\n<p>Das ist eine Bewertungsidentität, keine Schätzung der tatsächlichen\nAufwärtswahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>.\nSie entsteht aus der Replikation. Für nichtnegative Auszahlungen ist der\nPreis nichtnegativ und liegt zwischen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">min<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>H<\/mi><mi>u<\/mi><\/msub><mo>,<\/mo><msub><mi>H<\/mi><mi>d<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\min(H_u,H_d)/R<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">max<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>H<\/mi><mi>u<\/mi><\/msub><mo>,<\/mo><msub><mi>H<\/mi><mi>d<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\max(H_u,H_d)/R<\/annotation><\/semantics><\/math>.\nFür zwei geordnete Auszahlungsvektoren sind auch die Preise geordnet,\nstrikt bei mindestens einer strikten Zustandsungleichung. Diese\nEigenschaften folgen aus den positiven Gewichten.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_043_DE.svg\"\nalt=\"Einperiodenbaum mit Aktienwerten, Zahlungsansprüchen, replizierendem Portfolio und risikoneutralen Gewichten.\" />\n<figcaption aria-hidden=\"true\">Einperiodenbaum mit Aktienwerten,\nZahlungsansprüchen, replizierendem Portfolio und risikoneutralen\nGewichten.<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Grenzen<\/h2>\n<p>Wähle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=100<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u<\/mi><mo>=<\/mo><mn>6<\/mn><mi>/<\/mi><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u=6/5<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mn>4<\/mn><mi>/<\/mi><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d=4/5<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>21<\/mn><mi>/<\/mi><mn>20<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R=21/20<\/annotation><\/semantics><\/math>.\nEin europäischer Call mit Ausübungspreis 100 zahlt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>20<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(20,0)<\/annotation><\/semantics><\/math>.\nDamit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=1/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c<\/mi><mo>=<\/mo><mi>−<\/mi><mn>800<\/mn><mi>/<\/mi><mn>21<\/mn><\/mrow><annotation encoding=\"application/x-tex\">c=-800/21<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>5<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q=5/8<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>250<\/mn><mi>/<\/mi><mn>21<\/mn><mo>≈<\/mo><mn>11<\/mn><mo>,<\/mo><mn>90<\/mn><\/mrow><annotation encoding=\"application/x-tex\">H_0=250/21\\approx11{,}90<\/annotation><\/semantics><\/math>.\nIm oberen Zustand ist der Aktienanteil 60 wert, die Schuld beträgt 40;\nunten sind es 40 und 40. So entstehen genau 20 bzw. 0. Für einen Put mit\ngleichem Ausübungspreis ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>20<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">H=(0,20)<\/annotation><\/semantics><\/math>,\nsein Preis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>50<\/mn><mi>/<\/mi><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">50/7<\/annotation><\/semantics><\/math>.\nDie Put-Call-Parität folgt aus der zustandsweisen Identität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>P<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><msub><mi>S<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><mi>K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">C_1-P_1=S_1-K<\/annotation><\/semantics><\/math>:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>P<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mi>s<\/mi><mo>−<\/mo><mi>K<\/mi><mi>/<\/mi><mi>R<\/mi><mo>=<\/mo><mn>100<\/mn><mi>/<\/mi><mn>21<\/mn><\/mrow><annotation encoding=\"application/x-tex\">C_0-P_0=s-K/R=100/21<\/annotation><\/semantics><\/math>.\nDies ist ein Konsistenztest.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> fractions <span class=\"im\">import<\/span> Fraction <span class=\"im\">as<\/span> F<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> replicate(s, u, d, R, hu, hd):<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    s, u, d, R, hu, hd <span class=\"op\">=<\/span> <span class=\"bu\">map<\/span>(F, (s,u,d,R,hu,hd))<\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">if<\/span> <span class=\"kw\">not<\/span> (s <span class=\"op\">&gt;<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">and<\/span> <span class=\"dv\">0<\/span> <span class=\"op\">&lt;<\/span> d <span class=\"op\">&lt;<\/span> R <span class=\"op\">&lt;<\/span> u):<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;strict no-arbitrage condition required&quot;<\/span>)<\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    delta <span class=\"op\">=<\/span> (hu<span class=\"op\">-<\/span>hd)<span class=\"op\">/<\/span>(s<span class=\"op\">*<\/span>(u<span class=\"op\">-<\/span>d))<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    cash <span class=\"op\">=<\/span> (u<span class=\"op\">*<\/span>hd<span class=\"op\">-<\/span>d<span class=\"op\">*<\/span>hu)<span class=\"op\">/<\/span>(R<span class=\"op\">*<\/span>(u<span class=\"op\">-<\/span>d))<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    q <span class=\"op\">=<\/span> (R<span class=\"op\">-<\/span>d)<span class=\"op\">/<\/span>(u<span class=\"op\">-<\/span>d)<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    price <span class=\"op\">=<\/span> s<span class=\"op\">*<\/span>delta<span class=\"op\">+<\/span>cash<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">assert<\/span> price <span class=\"op\">==<\/span> (q<span class=\"op\">*<\/span>hu<span class=\"op\">+<\/span>(<span class=\"dv\">1<\/span><span class=\"op\">-<\/span>q)<span class=\"op\">*<\/span>hd)<span class=\"op\">/<\/span>R<\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> delta, cash, q, price<\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"bu\">print<\/span>(replicate(<span class=\"dv\">100<\/span>, F(<span class=\"dv\">6<\/span>,<span class=\"dv\">5<\/span>), F(<span class=\"dv\">4<\/span>,<span class=\"dv\">5<\/span>), F(<span class=\"dv\">21<\/span>,<span class=\"dv\">20<\/span>), <span class=\"dv\">20<\/span>, <span class=\"dv\">0<\/span>))<\/span><\/code><\/pre><\/div>\n<p>Die Brüche vermeiden Rundungsfehler; Dezimalparameter als\nZeichenkette oder exakter Bruch eingeben, nicht als binären\nGleitkommawert. Ohne die idealisierten Annahmen (etwa bei Gebühren,\nHandelsbeschränkungen oder mehr Zuständen als unabhängigen Basiswerten)\nkann die Replikation scheitern; dann existiert unter Umständen kein\neindeutiger Preis. Im Mehrperiodenmodell kann man unter analogen\nAnnahmen an jedem Knoten rückwärts replizieren; die dynamische\nHandelsstrategie muss selbstfinanzierend sein. Dieses Beispiel ist keine\nAnlageempfehlung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Prüfe Arbitragefreiheit bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>50<\/mn><mo>,<\/mo><mi>d<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>9<\/mn><mo>,<\/mo><mi>u<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=50,d=0{,}9,u=1{,}1,R=1{,}1<\/annotation><\/semantics><\/math>.\nGib eine Nullkostenposition an.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>q<\/mi><annotation encoding=\"application/x-tex\">q<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>7<\/mn><mo>,<\/mo><mi>u<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>3<\/mn><mo>,<\/mo><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">d=0{,}7,u=1{,}3,R=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Bestimme die Replikation einer konstanten Zahlung 9 bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>125<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R=1{,}125<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Berechne den Put-Preis des Beispiels aus dem risikoneutralen Maß und\nkontrolliere die Parität.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Die tatsächliche Aufwärtswahrscheinlichkeit ist 0,9. Ändert das im\nBeispiel den Call-Preis? Begründe.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Nein,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R<\/mi><mo>=<\/mo><mi>u<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R=u<\/annotation><\/semantics><\/math>.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mi>c<\/mi><mo>=<\/mo><mn>50<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=-1,c=50<\/annotation><\/semantics><\/math>\nliefert oben 0 und unten 10.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><mn>7<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>3<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><mn>7<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(1-0{,}7)/(1{,}3-0{,}7)=1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mi>c<\/mi><mo>=<\/mo><mn>9<\/mn><mi>/<\/mi><mn>1<\/mn><mo>,<\/mo><mn>125<\/mn><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=0,c=9/1{,}125=8<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>20<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>21<\/mn><mi>/<\/mi><mn>20<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>50<\/mn><mi>/<\/mi><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">20(3/8)/(21/20)=50/7<\/annotation><\/semantics><\/math>;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>250<\/mn><mi>/<\/mi><mn>21<\/mn><mo>−<\/mo><mn>50<\/mn><mi>/<\/mi><mn>7<\/mn><mo>=<\/mo><mn>100<\/mn><mi>/<\/mi><mn>21<\/mn><\/mrow><annotation encoding=\"application/x-tex\">250/21-50/7=100/21<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Nein. Solange beide Zustände positive tatsächliche\nWahrscheinlichkeit besitzen, bleibt die Replikation unverändert;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>q<\/mi><mo>=<\/mo><mn>5<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">q=5/8<\/annotation><\/semantics><\/math>\nist durch die Preise bestimmt.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.maths.dur.ac.uk/users/clare.wallace/MF/Chapter2.html\">Clare\nWallace, Durham University: Mathematical Finance, Chapter 2<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> ·\n§2.2–2.5 · Zuletzt abgerufen: 2026-11-24 · Inhaltlich geprüft:\n2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>","university_mathematics_de:M9-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M9-L5 – Versicherungsrisiko und kollektives Risikomodell<\/h1>\n<p><strong>Kursbereich:<\/strong> M9 – Stochastik, Finanz- und Versicherungsmathematik<\/p>\n<p><strong>Niveau:<\/strong> Master · Wahlpflicht<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_mathematics&amp;module=M1&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">M1-L7<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M3&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M3-L4<\/a>; <a\nhref=\"index.html?course=university_mathematics&amp;module=M9&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M9-L1<\/a><\/p>\n<p><strong>Einordnung:<\/strong> Master-Wahlpflichtvertiefung<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lernziele<\/h2>\n<p>Du modellierst eine zufällige Gesamtschadenssumme, leitest deren\nErwartungswert und Varianz durch Konditionierung her und berechnest eine\nendliche Schadensverteilung durch Faltung. Du unterscheidest mittleren\nSchaden, Schwankungsrisiko und Modellrisiko.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Schadenanzahl und Schadenhöhe<\/h2>\n<p>Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\ndie nichtnegative ganzzahlige Anzahl von Schäden innerhalb eines festen\nZeitraums. Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mi>i<\/mi><\/msub><msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mrow><mi>i<\/mi><mo>≥<\/mo><mn>1<\/mn><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">(X_i)_{i\\ge1}<\/annotation><\/semantics><\/math>\neine Folge unabhängiger, identisch verteilter nichtnegativer\nSchadenhöhen, unabhängig von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>.\nDie Gesamtsumme ist<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>N<\/mi><\/munderover><msub><mi>X<\/mi><mi>i<\/mi><\/msub><mo>,<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S=\\sum_{i=1}^{N}X_i,<\/annotation><\/semantics><\/math><\/p>\n<p>wobei bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=0<\/annotation><\/semantics><\/math>\ndie leere Summe null ist. Das Modell beschreibt ein Portfolio, nicht\nzwingend einzelne Verträge. Alle Beträge werden in derselben Geldeinheit\nund zum selben Bewertungszeitpunkt gemessen. Wir setzen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>N<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>&lt;<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[N^2]&lt;\\infty<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>X<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>&lt;<\/mo><mi>∞<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[X_1^2]&lt;\\infty<\/annotation><\/semantics><\/math>\nvoraus. Schreibe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mu=E[X_1]<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\sigma^2=\\operatorname{Var}(X_1)<\/annotation><\/semantics><\/math>.\nFrequenz und Schweregrad werden getrennt modelliert; ein einzelner\ngroßer Schaden kann trotz kleiner Anzahl erheblich sein.<\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Momente durch Konditionierung<\/h2>\n<p>Bei gegebenem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">N=n<\/annotation><\/semantics><\/math>\nbesitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>S<\/mi><annotation encoding=\"application/x-tex\">S<\/annotation><\/semantics><\/math>\ndie Verteilung einer Summe aus genau\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nunabhängigen Kopien von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mn>1<\/mn><\/msub><annotation encoding=\"application/x-tex\">X_1<\/annotation><\/semantics><\/math>.\nLinearität der Erwartung und verschwindende Kovarianzen ergeben\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo>∣<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>N<\/mi><mi>μ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[S\\mid N]=N\\mu<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>∣<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>N<\/mi><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(S\\mid N)=N\\sigma^2<\/annotation><\/semantics><\/math>.\nAus der Turmeigenschaft (siehe <a\nhref=\"index.html?course=university_mathematics&amp;module=M9&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M9-L1<\/a>) und der Zerlegung der\nGesamtvarianz folgt<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>μ<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>μ<\/mi><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[S]=E[N]\\mu,\\qquad \\operatorname{Var}(S)=E[N]\\sigma^2+\\operatorname{Var}(N)\\mu^2.<\/annotation><\/semantics><\/math><\/p>\n<p>Zur Begründung der zweiten Zerlegung schreibe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>−<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>−<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo>∣<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo>∣<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>−<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S-E[S]=(S-E[S\\mid N])+(E[S\\mid N]-E[S])<\/annotation><\/semantics><\/math>.\nDer gemischte Term des quadrierten Ausdrucks hat Erwartung null, weil\nder erste Summand bedingt auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nMittelwert null hat und der zweite von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nabhängt. Die beiden verbleibenden Quadrate liefern die Formel. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>∼<\/mo><mrow><mi mathvariant=\"normal\">Poisson<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>λ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">N\\sim\\operatorname{Poisson}(\\lambda)<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mi>λ<\/mi><mi>μ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E[S]=\\lambda\\mu<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>λ<\/mi><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msubsup><mi>X<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(S)=\\lambda E[X_1^2]<\/annotation><\/semantics><\/math>.\nDer zweite Rohmoment ist nicht die Varianz: Auch konstante Schadenhöhen\nerzeugen durch die zufällige Anzahl Schwankungen.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Verteilung und vollständiges Beispiel<\/h2>\n<p>Bei ganzzahligen Schadenhöhen mit erzeugender Funktion\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>G<\/mi><mi>X<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>z<\/mi><mi>X<\/mi><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">G_X(z)=E[z^X]<\/annotation><\/semantics><\/math>\ngilt für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>≤<\/mo><mi>z<\/mi><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0\\le z\\le1<\/annotation><\/semantics><\/math>\ndie Identität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>G<\/mi><mi>S<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>G<\/mi><mi>N<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>G<\/mi><mi>X<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">G_S(z)=G_N(G_X(z))<\/annotation><\/semantics><\/math>,\ndenn bedingt auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mi>n<\/mi><\/mrow><annotation encoding=\"application/x-tex\">N=n<\/annotation><\/semantics><\/math>\nfaktorisiert die Erwartung des Produkts zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>G<\/mi><mi>X<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>n<\/mi><\/msup><\/mrow><annotation encoding=\"application/x-tex\">G_X(z)^n<\/annotation><\/semantics><\/math>.\nFür Poisson-Frequenz ist dies\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">exp<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>λ<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>G<\/mi><mi>X<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>z<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\exp(\\lambda(G_X(z)-1))<\/annotation><\/semantics><\/math>.\nFür endliche Verteilungen lassen sich alle Koeffizienten durch\nwiederholte Faltung exakt ermitteln.<\/p>\n<p>Beispiel:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>N<\/mi><mo>=<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(N=0)=1/4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>N<\/mi><mo>=<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(N=2)=3/4<\/annotation><\/semantics><\/math>;\nunabhängig davon ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>X<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">X=1<\/annotation><\/semantics><\/math>\noder\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>3<\/mn><annotation encoding=\"application/x-tex\">3<\/annotation><\/semantics><\/math>\nmit je Wahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/2<\/annotation><\/semantics><\/math>.\nDann\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[N]=3/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(N)=3/4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>μ<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mu=2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>σ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma^2=1<\/annotation><\/semantics><\/math>.\nFolglich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[S]=3<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">Var<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>9<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{Var}(S)=9/2<\/annotation><\/semantics><\/math>.\nDie Verteilung lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>=<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(S=0)=1/4<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>=<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(S=2)=3/16<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>=<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(S=4)=3/8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>=<\/mo><mn>6<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(S=6)=3/16<\/annotation><\/semantics><\/math>.\nDie Wahrscheinlichkeit für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>&gt;<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S&gt;4<\/annotation><\/semantics><\/math>\nbeträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3/16<\/annotation><\/semantics><\/math>.\nDie Summe der Wahrscheinlichkeiten ist eins; die Momente aus den vier\nAtomen stimmen mit der allgemeinen Formel überein.<\/p>\n<figure>\n<img src=\"../learning-courses-university-mathematics-de/media/img/U_MAT_044_DE.svg\"\nalt=\"Vier Schadenswerte mit ihren Wahrscheinlichkeiten\" />\n<figcaption aria-hidden=\"true\">Vier Schadenswerte mit ihren\nWahrscheinlichkeiten<\/figcaption>\n<\/figure>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Berechnung und Modellgrenzen<\/h2>\n<p>Die folgende Funktion faltet die Schadenhöhenverteilung schrittweise\nund gewichtet die Resultate mit der Anzahlverteilung. Sie ist für kleine\nendliche Modelle mit exakten rationalen Wahrscheinlichkeiten gedacht,\nnicht für unbeschränkte Poisson-Verteilungen.<\/p>\n<div class=\"sourceCode\" id=\"cb1\"><pre\nclass=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"im\">from<\/span> fractions <span class=\"im\">import<\/span> Fraction <span class=\"im\">as<\/span> F<\/span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"kw\">def<\/span> aggregate(count, severity):<\/span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"co\"># Finite probability mass functions: nonnegative integer keys.<\/span><\/span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">for<\/span> pmf <span class=\"kw\">in<\/span> (count, severity):<\/span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">if<\/span> (<span class=\"kw\">not<\/span> pmf <span class=\"kw\">or<\/span> <span class=\"bu\">any<\/span>(<span class=\"bu\">type<\/span>(k) <span class=\"kw\">is<\/span> <span class=\"kw\">not<\/span> <span class=\"bu\">int<\/span> <span class=\"kw\">or<\/span> k <span class=\"op\">&lt;<\/span> <span class=\"dv\">0<\/span> <span class=\"kw\">or<\/span> v <span class=\"op\">&lt;<\/span> <span class=\"dv\">0<\/span><\/span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                          <span class=\"cf\">for<\/span> k, v <span class=\"kw\">in<\/span> pmf.items())<\/span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                <span class=\"kw\">or<\/span> <span class=\"bu\">sum<\/span>(pmf.values()) <span class=\"op\">!=<\/span> <span class=\"dv\">1<\/span>):<\/span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>            <span class=\"cf\">raise<\/span> <span class=\"pp\">ValueError<\/span>(<span class=\"st\">&quot;invalid probability mass function&quot;<\/span>)<\/span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    result, current <span class=\"op\">=<\/span> {}, {<span class=\"dv\">0<\/span>: F(<span class=\"dv\">1<\/span>)}<\/span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">for<\/span> n <span class=\"kw\">in<\/span> <span class=\"bu\">range<\/span>(<span class=\"bu\">max<\/span>(count)<span class=\"op\">+<\/span><span class=\"dv\">1<\/span>):<\/span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">for<\/span> s, weight <span class=\"kw\">in<\/span> current.items():<\/span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>            result[s] <span class=\"op\">=<\/span> result.get(s, F(<span class=\"dv\">0<\/span>)) <span class=\"op\">+<\/span> count.get(n, <span class=\"dv\">0<\/span>)<span class=\"op\">*<\/span>weight<\/span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>        <span class=\"cf\">if<\/span> n <span class=\"op\">&lt;<\/span> <span class=\"bu\">max<\/span>(count):<\/span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>            new <span class=\"op\">=<\/span> {}<\/span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>            <span class=\"cf\">for<\/span> s, a <span class=\"kw\">in<\/span> current.items():<\/span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                <span class=\"cf\">for<\/span> x, b <span class=\"kw\">in<\/span> severity.items():<\/span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>                    new[s<span class=\"op\">+<\/span>x] <span class=\"op\">=<\/span> new.get(s<span class=\"op\">+<\/span>x, F(<span class=\"dv\">0<\/span>)) <span class=\"op\">+<\/span> a<span class=\"op\">*<\/span>b<\/span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>            current <span class=\"op\">=<\/span> new<\/span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\" tabindex=\"-1\"><\/a>    <span class=\"cf\">return<\/span> {s: w <span class=\"cf\">for<\/span> s, w <span class=\"kw\">in<\/span> <span class=\"bu\">sorted<\/span>(result.items()) <span class=\"cf\">if<\/span> w}<\/span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><\/span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\" tabindex=\"-1\"><\/a><span class=\"bu\">print<\/span>(aggregate({<span class=\"dv\">0<\/span>:F(<span class=\"dv\">1<\/span>,<span class=\"dv\">4<\/span>), <span class=\"dv\">2<\/span>:F(<span class=\"dv\">3<\/span>,<span class=\"dv\">4<\/span>)}, {<span class=\"dv\">1<\/span>:F(<span class=\"dv\">1<\/span>,<span class=\"dv\">2<\/span>), <span class=\"dv\">3<\/span>:F(<span class=\"dv\">1<\/span>,<span class=\"dv\">2<\/span>)}))<\/span><\/code><\/pre><\/div>\n<p>Der Nettorisikobeitrag\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E[S]<\/annotation><\/semantics><\/math>\nberücksichtigt weder Verwaltungskosten noch Kapitalbedarf. Ein\nStop-Loss-Vertrag mit Selbstbehalt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>a<\/mi><annotation encoding=\"application/x-tex\">a<\/annotation><\/semantics><\/math>\nzahlt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>S<\/mi><mo>−<\/mo><mi>a<\/mi><msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><\/msub><\/mrow><annotation encoding=\"application/x-tex\">(S-a)_+<\/annotation><\/semantics><\/math>;\nim Beispiel kostet die erwartete Auszahlung bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=4<\/annotation><\/semantics><\/math>\ngenau\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3/8<\/annotation><\/semantics><\/math>.\nAbhängigkeit kann die Formeln ändern: Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nmit gleicher Wahrscheinlichkeit 0 oder 2 und seien alle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>i<\/mi><\/msub><mo>=<\/mo><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X_i=N<\/annotation><\/semantics><\/math>;\ndann ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[S]=2<\/annotation><\/semantics><\/math>,\nobwohl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[N]E[X_1]=1<\/annotation><\/semantics><\/math>.\nGemeinsame Katastrophenfaktoren und schwere Verteilungsschwänze\nverlangen eigene Modelle. Endliche Momente garantieren keine geringe\nÜberschreitungswahrscheinlichkeit. Die Zahlen sind reine Lehrmodelle und\nkeine Tarif- oder Solvenzempfehlungen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme Erwartung und Varianz für konstante Schadenhöhe 5 und\nPoisson-Anzahl mit Parameter 4.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne die Varianz im Beispiel direkt aus der Verteilung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Bestimme die Wahrscheinlichkeit für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>≥<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S\\ge4<\/annotation><\/semantics><\/math>\nim Beispiel.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\">Berechne dort die erwartete Stop-Loss-Auszahlung bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\">Sei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=2<\/annotation><\/semantics><\/math>\nsicher und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X_1=X_2=Y<\/annotation><\/semantics><\/math>,\nwobei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>Y<\/mi><annotation encoding=\"application/x-tex\">Y<\/annotation><\/semantics><\/math>\ngleichwahrscheinlich 0 oder 2 ist. Vergleiche die tatsächliche Varianz\nmit der Formel für unabhängige Schadenhöhen.<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S6\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>20<\/mn><annotation encoding=\"application/x-tex\">20<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>100<\/mn><annotation encoding=\"application/x-tex\">100<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>S<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mo>=<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>16<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>36<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>27<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E[S^2]=4(3/16)+16(3/8)+36(3/16)=27/2<\/annotation><\/semantics><\/math>;\nminus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>9<\/mn><annotation encoding=\"application/x-tex\">9<\/annotation><\/semantics><\/math>\nergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>9<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">9/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><mo>+<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><mo>=<\/mo><mn>9<\/mn><mi>/<\/mi><mn>16<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3/8+3/16=9/16<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">4.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>3<\/mn><mi>/<\/mi><mn>16<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2(3/8)+4(3/16)=3/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">5.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><mn>2<\/mn><mi>Y<\/mi><\/mrow><annotation encoding=\"application/x-tex\">S=2Y<\/annotation><\/semantics><\/math>\nhat Varianz 4, statt 2 unter Unabhängigkeit. Der Kovarianzterm erklärt\ndie Differenz.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://openacttexts.github.io/LDAVer2/ChapAggLossModels.html\">Loss\nData Analytics, 2nd ed., Chapter 7<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · §7.3 · Zuletzt abgerufen:\n2026-11-24 · Inhaltlich geprüft: 2026-11-24<\/div><\/li>\n<\/ul>\n<\/article>"};
